TLM.f("Sancti/03-10",{"officium":"Ss. Quadraginta Martyrum","rule":["Evangelium non appropriatum","vide C3;","Gloria"],"fallback":"Commune/C3","from":{"Tractus":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Ps 33:18"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"ref","la":"Ps 33:2"},{"k":"text","la":"Benedícam Dóminum in omni témpore: semper laus ejus in ore meo."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."}],"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, qui gloriósos Mártyres fortes in sua confessióne cognóvimus, pios apud te in nostra intercessióne sentiámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos"},{"k":"ref","la":"Hebr 11:33-39"},{"k":"text","la":"Fratres: Sancti per fidem vicérunt regna, operáti sunt justítiam, adépti sunt repromissiónes, obturavérunt ora leónum, exstinxérunt ímpetum ignis, effugérunt áciem gládii, convaluérunt de infirmitáte, fortes facti sunt in bello, castra vertérunt exterórum: accepérunt mulíeres de resurrectióne mórtuos suos: álii autem disténti sunt, non suscipiéntes redemptiónem, ut meliórem invenírent resurrectiónem: alii vero ludíbria et vérbera expérti, ínsuper et víncula et cárceres: lapidáti sunt, secti sunt, tentáti sunt, in occisióne gládii mórtui sunt: circuiérunt in melótis, in péllibus caprínis, egéntes, angustiáti, afflicti: quibus dignus non erat mundus: in solitudínibus errantes, in móntibus et spelúncis et in cavérnis terræ. Et hi omnes testimónio fídei probáti, invénti sunt in Christo Jesu, Dómino nostro."}],"Graduale":[{"k":"ref","la":"Ps 132:1-2"},{"k":"text","la":"Ecce, quam bonum et quam jucúndum, habitáre fratres in unum!"},{"k":"text","la":"Sicut unguéntum in cápite, quod descéndit in barbam, barbam Aaron.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et fiébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 6:17-23"},{"k":"text","la":"In illo témpore: Descéndens Jesus de monte, stetit in loco campéstri, et turba discipulórum ejus, et multitúdo copiósa plebis ab omni Judǽa, et Jerúsalem, et marítima, et Tyri, et Sidónis, qui venérant, ut audírent eum et sanaréntur a languóribus suis. Et, qui vexabántur a spirítibus immúndis, curabántur. Et omnis turba quærébat eum tángere: quia virtus de illo exíbat, et sanábat omnes. Et ipse, elevátis oculis in discípulos suos, dicébat: Beáti, páuperes: quia vestrum est regnum Dei. Beáti, qui nunc esurítis: quia saturabímini. Beáti, qui nunc fletis: quia ridébitis. Beáti éritis, cum vos óderint hómines, et cum separáverint vos et exprobréverint, et ejécerint nomen vestrum tamquam malum, propter Fílium hóminis. Gaudéte in illa die et exsultáte: ecce enim, merces vestra multa est in cœlo."}],"Offertorium":[{"k":"ref","la":"Ps 31:11"},{"k":"text","la":"Lætámini in Dómino et exsultáte, justi: et gloriámini, omnes recti corde."}],"Secreta":[{"k":"text","la":"Preces, Dómine, tuórum réspice oblationésque fidélium: ut et tibi gratæ sint pro tuórum festivitáte Sanctórum, et nobis cónferant tuæ propitiatiónis auxílium."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 12:50"},{"k":"text","la":"Quicúmque fécerit voluntátem Patris mei, qui in cœlis est: ipse meus frater et soror et mater est, dicit Dóminus."}],"Postcommunio":[{"k":"text","la":"Sanctórum tuórum, Dómine, intercessióne placátus: præsta, quǽsumus; ut, quæ temporáli celebrámus actióne, perpétua salvatióne capiámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"68887bdeda17172c":{"t":"<i>Pomolimo se</i>.\nDaj, molimo, svemogući Bože, da mi koji smo slavne mučenike upoznali da su bili jaki u svom mučeništvu, osjetimo da su dobrostivi kad nas zagovaraju kod tebe.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemogući Bože, da mi, koji smo slavne mučenike spoznali neustrašivima u njihovom mučeništvu, . osjetimo njihov blagi zagovor kod Tebe, po G. n.","knRef":"Kniewald 1942, str. 634–635 (snimka 318) (OCR)"},"db8921a4d107e2d5":{"t":"Pogledaj, Gospodine, na molitve i prinose svojih vjernika, da budu i tebi mili zbog svetkovine tvojih svetih i nama donesu tvoju milostivu pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pogledaj, Gospodine, molitve i žrtve Tvojih vjernika, da Ti budu drage, jer ih prinosimo o svetkovini Tvojih svetih, a nama da pruže pomoć Tvojeg pomirenja, po G. n.","knRef":"Kniewald 1942, str. 522–523 (snimka 262) (OCR)"},"0557456d36d8e952":{"t":"<i>Pomolimo se</i>.\nUmilostivljen, Gospodine, posredovanjem tvojih svetih, daj, molimo, da postignemo u trajnom spasenju što slavimo vremenitim činom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
